using System;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Web.Script.Serialization;using ReplierDesktop;
public static class SceneReactionChecks {
 static string Ordinary(object body){var j=new JavaScriptSerializer();var req=SceneMaterial.Json(j.Serialize(body));var messages=(object[])CaptionService.Get(req,"messages");var input=SceneMaterial.Json((string)CaptionService.Get(messages.Last(),"content"));var words=(object[])CaptionService.Get(input,"words");return j.Serialize(new{word_kinds=words.Select(w=>new{id=(int)CaptionService.Get(w,"id"),kind="ordinary_expression"}).ToArray()});}
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);Console.WriteLine("PASS "+name);}
 public static int Main(){try{var json=new JavaScriptSerializer();var video=new Video{Id="V0000000001",Title="좋은 결과인데 아쉬웠던 강화"};var content=new VideoContent{Version=1,VideoId=video.Id,Language="ko",Source="YouTube 공개 자막",AcquiredAt=DateTime.UtcNow.ToString("o"),Cues=new List<CaptionCue>{new CaptionCue{Text="돈을 많이 썼습니다. 정말 떴어 축하야! 잘 뜬 건 맞지만 너무 아깝네요."}}};
 using(var model=new LocalModel("unused")){
 var planner=new ScenePlanner(model,(body,t)=>{var o=SceneMaterial.Json(json.Serialize(body));var messages=(object[])CaptionService.Get(o,"messages");string input=(string)CaptionService.Get(messages.Last(),"content");Check(input.Contains(video.Title)&&input.Contains("돈을 많이")&&input.Contains("아깝"),"reader sees full title process and mixed outcome instead of isolated celebration");return Task.FromResult(json.Serialize(new{subject="장비 옵션/강화 작업",process="큰 비용이 드는 과정",outcome="좋은 점과 아쉬운 점이 함께 있음",mood="기쁨과 아쉬움이 함께 있음",keywords=new[]{"돈","절대 없는 순위"},evidence=new[]{0}}));});
 var materials=planner.Prepare(video,content,CancellationToken.None).GetAwaiter().GetResult();Check(!materials.Values.First().Contains("절대 없는 순위"),"reader cannot inject a keyword absent from the supplied original");
 Check(materials.Values.All(SceneMaterial.IsScene),"scene material explicitly separates interpretation from preserved original sources");
 int writes=0;string[] drafts={"잘 뜬 건 맞는데 쓴 돈 생각하면 마냥 웃기도 어렵네요 ㅋㅋ","잘 나왔는데도 아쉬운 마음은 알 것 같네요","좋은 결과가 나와서 그나마 다행이네요","보는 동안 돈 나가는 게 더 신경 쓰였네요","과정이 길어서 마지막이 더 반갑네요"};
 var writer=new SceneWriter(model,(body,t)=>{writes++;var o=SceneMaterial.Json(json.Serialize(body));var messages=(object[])CaptionService.Get(o,"messages");string input=(string)CaptionService.Get(messages.Last(),"content");Check(input.Contains("축하야")&&input.Contains("actual_context")&&input.Contains("whole_context")&&!input.Contains("기쁨과 아쉬움"),"writer receives actual local context without an inferred negative emotion or mandatory source phrase");return Task.FromResult(json.Serialize(new{comments=new[]{drafts[(writes-1)%5]}}));});
 var result=writer.Generate(CommentService.Evidence(content,video.Title),materials,new string[0],CancellationToken.None,(text,id,keys)=>new CommentSuggestion{Text=text,CueId=id,Evidence=content.Cues[0].Text},content.Cues.Count).GetAwaiter().GetResult();Check(result.Comments.Count==5&&writes==5&&result.Comments.All(c=>c.FitEligible==false),"five reactions keep casual draft voice and stay unverified until independent grading");
 Check(result.ContextSummary.Contains("감정 분류는 작성에 사용하지 않음"),"debug distinguishes original context from unused emotional classification");
 var evidence=CommentService.Evidence(content,video.Title).ToArray();var rows=result.Comments.Take(1).ToArray();
 Func<string,string,string,string,string> response=(voice,relation,kind,point)=>json.Serialize(new{ratings=new[]{new{id=0,voice=voice,relation=relation,response=kind,point=point,evidence=new[]{0},topic=20,tone=10,care=5,link=15}}});
 Check(SceneFitScoring.Parse(response("viewer","supported","reaction","마냥 웃기도 어렵네요"),rows,evidence)[0].Eligible,"semantic viewer reaction can pass without copying the source sentence");
 foreach(var values in new[]{new[]{"awkward","supported","reaction"},new[]{"retelling","supported","paraphrase"},new[]{"viewer","unsupported","reaction"},new[]{"viewer","supported","generic"}})Check(!SceneFitScoring.Parse(response(values[0],values[1],values[2],"마냥 웃기도 어렵네요"),rows,evidence)[0].Eligible,"maximum numbers cannot override absolute voice meaning or reaction failure: "+string.Join("/",values));
 Check(!SceneFitScoring.Parse(response("viewer","supported","reaction","없는 신화 확률"),rows,evidence)[0].Eligible,"assessment cannot attach a comment point that the original comment never contained");
 bool rejected=false;try{SceneFitScoring.Parse(json.Serialize(new{ratings=new[]{new{id=0,voice="viewer",relation="supported",response="reaction",point="마냥 웃기도 어렵네요",evidence=new[]{7},topic=20,tone=10,care=5,link=15}}}),rows,evidence);}catch(System.IO.InvalidDataException){rejected=true;}Check(rejected,"fabricated transcript references rejected");
 int judgingCalls=0;var independent=new FitScoring(model,(body,t)=>{judgingCalls++;var req=SceneMaterial.Json(json.Serialize(body));var props=CaptionService.Get(CaptionService.Get(req,"format"),"properties");var messages=(object[])CaptionService.Get(req,"messages");string last=(string)CaptionService.Get(messages.Last(),"content");var input=last.StartsWith("평가할 댓글:")?SceneMaterial.Json(((string)CaptionService.Get(messages[messages.Length-3],"content")).Substring("영상 참고자료: ".Length)):SceneMaterial.Json(last);
 if(CaptionService.Get(props,"references")!=null)return Task.FromResult("{\"references\":[]}");if(CaptionService.Get(props,"voices")!=null){Check(CaptionService.Get(input,"transcript")==null&&CaptionService.Get(input,"scene")==null,"voice judgment receives no video or analysis that could excuse awkward wording");return Task.FromResult(json.Serialize(new{voices=new[]{new{id=0,voice="viewer"}}}));}
 if(CaptionService.Get(props,"references")!=null)return Task.FromResult("{\"references\":[]}");if(CaptionService.Get(props,"source")!=null)return Task.FromResult(json.Serialize(new{evaluated_comment=(string)CaptionService.Get(input,"candidate_comment"),supported=true,context_clear=true,added_claim=false,asserts_event_result=false,source_kind="no_event",comment_outcome="none",context_outcome="undetermined",source=0,quote="돈을 많이 썼습니다."}));
 Check(CaptionService.Get(input,"scene")==null&&CaptionService.Get(input,"transcript")!=null,"semantic judgment reads original context without being anchored by the generated interpretation");return Task.FromResult("{\"evaluated_comment\":\"잘 뜬 건 맞는데 쓴 돈 생각하면 마냥 웃기도 어렵네요 ㅋㅋ\",\"focus\":\"많은 비용과 복합적인 결과\",\"explanation\":\"쓴 돈에 대한 시청자 반응\",\"quote\":\"돈을 많이 썼습니다.\",\"target\":\"쓴 돈\",\"source_role\":\"central_event\",\"response\":\"reaction\",\"conflicts\":false,\"evidence\":0}");});
 var independentResult=independent.Assess(video,content,rows,CancellationToken.None).GetAwaiter().GetResult();Check(judgingCalls==4&&independentResult[0].Eligible,"production scorer routes scene comments through independent voice and context reviews");
 var report=CommentDebugReport.Format(video,new DualCommentResult{Complete=true,Batches=new List<ModelCommentBatch>{new ModelCommentBatch{Model="test",Label="test",Result=result}}},null,"검사용","");Check(report.Contains("작성 전 상황 이해")&&report.Contains("감정 분류는 작성에 사용하지 않음"),"copied debug report exposes context understanding alongside candidates");
 }return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
